const recalculateReconciliationCounters = `-- name: RecalculateReconciliationCounters :one
UPDATE reconciliations r
SET scanned_count = c.scanned, matched_count = c.matched,
    missing_count = c.missing, excess_count = c.excess, damaged_count = c.damaged
FROM (
    SELECT count(*) FILTER (WHERE scanned_at IS NOT NULL) AS scanned,
           count(*) FILTER (WHERE outcome = 'MATCHED') AS matched,
           count(*) FILTER (WHERE outcome = 'MISSING') AS missing,
           count(*) FILTER (WHERE outcome = 'EXCESS') AS excess,
           count(*) FILTER (WHERE outcome = 'DAMAGED') AS damaged
    FROM reconciliation_items WHERE reconciliation_id = $1
) c
WHERE r.id = $1
RETURNING r.id, r.public_id, r.organization_id, r.reconciliation_code, r.subject_type, r.bag_id, r.manifest_id, r.trip_id, r.operating_unit_id, r.status, r.expected_count, r.scanned_count, r.matched_count, r.missing_count, r.excess_count, r.damaged_count, r.started_at, r.started_by_user_id, r.completed_at, r.completed_by_user_id, r.remarks, r.metadata, r.created_at, r.updated_at, r.version
`

